#nullable enable
using System;
using System.Drawing;
using System.IO;
using System.Linq;
using Inkybot.Dofus;
using Inkybot.Dofus.Domain;
using Inkybot.Dofus.Contracts;
using System.Windows.Forms;

namespace Script.Gelano
{
    public class Script : DofusMagingAI
    {
        #region Form
        private sealed class ConfigForm : Form
        {
            private readonly Font Font = new Font("Calibri", 9F, FontStyle.Regular, GraphicsUnit.Point, 0);
            private readonly Font FontBold = new Font("Calibri", 9F, FontStyle.Bold, GraphicsUnit.Point, 0);
            private Label overmageLabel;
            private ComboBox overmageComboBox;
            private Script script;

            public ConfigForm(Script script) {
                SuspendLayout();
                Size = MinimumSize = MaximumSize = new Size(400, 300);
                FormBorderStyle = FormBorderStyle.FixedSingle;
                MaximizeBox = false;
                AddComponents();
                var iconBitmap = ImageFromBase64(Icon_Base64);
                Icon = Icon.FromHandle(iconBitmap.GetHicon());
                this.script = script;
                
                ResumeLayout(false);
            }

            private void AddComponents() {
                Text = "Gelano Maging AI";
                var label = new Label {
                    Text = "Overmage stat",
                    AutoSize = true,
                    Font = Font,
                    Dock = DockStyle.Left,
                    Padding = new Padding(0, 2, 10, 2),
                };
                overmageComboBox = new ComboBox {
                    Text = "Select stat",
                    DataSource = Stat.Stats.Values.Except(new []{ Stat.Ap, Stat.Mp}).Select(stat => stat.DisplayName).Prepend("None").ToArray(),
                    Dock = DockStyle.Fill,
                };

                var okButton = new Button {
                    Text = "OK",
                    Height = 30,
                    Dock = DockStyle.Left,
                    Padding = new Padding(10, 0, 10, 0)
                };
                var cancelButton = new Button {
                    Text = "Cancel",
                    Height = 30,
                    Dock = DockStyle.Left,
                };
                var authorLabel = new Label {
                    Text = "by Association",
                    Font = Font,
                    Dock = DockStyle.Right,
                    AutoSize = false,
                    TextAlign = ContentAlignment.MiddleRight,
                };
                var apLabel = new Label {
                    Text = "1 AP",
                    AutoSize = true,
                    Font = FontBold,
                    ForeColor = Color.FromArgb(10, 10, 10),
                    BackColor = Color.Transparent,
                };
                var mpLabel = new Label {
                    Text = "1 MP",
                    AutoSize = true,
                    Font = FontBold,
                    ForeColor = Color.FromArgb(100, 100, 100),
                    BackColor = Color.Transparent,
                };
                overmageLabel = new Label {
                    Text = "50 Vitality",
                    AutoSize = true,
                    Font = FontBold,
                    ForeColor = Color.FromArgb(100, 100, 100),
                    BackColor = Color.Transparent,
                    Visible = false
                };
                
                var previewPanel = new FlowLayoutPanel {
                    Dock = DockStyle.Fill,
                    Padding = new Padding(90, 60, 0, 0),
                    BackgroundImage = ImageFromBase64(Bg_Base64),
                    BackgroundImageLayout = ImageLayout.Zoom,
                    FlowDirection = FlowDirection.TopDown,
                    Controls = { apLabel, mpLabel, overmageLabel }
                };
                var actionPanel = new Panel {
                    Dock = DockStyle.Bottom,
                    BackColor = SystemColors.ControlLight,
                    Height = 45,
                    Padding = new Padding(15, 5, 5, 5),
                    Controls = { cancelButton, okButton, authorLabel }
                };
                
                var topPanel = new Panel {
                    Dock = DockStyle.Top,
                    Controls = { overmageComboBox, label },
                    Height = 30
                };
                
                var mainPanel = new Panel {
                    Dock = DockStyle.Fill,
                    Padding = new Padding(5),
                    Controls = { previewPanel, topPanel}
                };
                Controls.AddRange(new Control[] { mainPanel, actionPanel });
                
                overmageComboBox.SelectedIndexChanged += OnOvermageComboBoxSelectedIndexChanged;
                okButton.Click += OnOkButtonClick;
                cancelButton.Click += OnCancelButtonClick;
            }

            private void OnOvermageComboBoxSelectedIndexChanged(object sender, EventArgs e) {
                var stat = StatFromOvermageComboBox();
                
                overmageLabel.Visible = stat != null;
                if (stat == null)
                    return;
                overmageLabel.Text = stat.StrongestRune.IncreaseInValue + " " +stat.DisplayName;
            }

            private void OnOkButtonClick(object sender, EventArgs e) {
                DialogResult = DialogResult.OK;
                script.Configure(StatFromOvermageComboBox());
            }

            private void OnCancelButtonClick(object sender, EventArgs e) {
                DialogResult = DialogResult.Cancel;
            }

            private Stat? StatFromOvermageComboBox() {
                if (overmageComboBox.SelectedIndex == 0)
                    return null;
                return Stat.Stats.Values.First(searched => searched.DisplayName == overmageComboBox.Text);
            }

            private Bitmap ImageFromBase64(string text) {
                var bytes = Convert.FromBase64String(text);
                using (var iconStream = new MemoryStream(bytes, 0, bytes.Length)) {
                    var image = (Bitmap) Image.FromStream(iconStream, true);
                    return image;
                }
            }
        }
        #endregion
        
        private bool IsConfiguredForOvermage => ConfiguredForOvermage != null;
        private Stat? ConfiguredForOvermage;
        private int OvermageTargetValue => ConfiguredForOvermage?.StrongestRune.IncreaseInValue ?? 0;
        
        private void Configure(Stat? overmage) {
            ConfiguredForOvermage = overmage;
        }

        public override void Init() {
            new ConfigForm(this).ShowDialog();
        }
        
        protected override IAction Resolve(Item item) {
            if (!item.HasStat(Stat.Mp))
                return CombineExo(item);

            if (!item.HasStat(Stat.Ap))
                return CombineApBack();

            return Finish();
        }

        public IAction CombineExo(Item item) {
            if (!IsConfiguredForOvermage)
                return Combine(Stat.Mp);

            if (!item.HasStat(ConfiguredForOvermage!))
                return Combine(ConfiguredForOvermage);
            
            if (item.Stats[ConfiguredForOvermage]!.Value < OvermageTargetValue)
                return Combine(ConfiguredForOvermage);
                    
            return Combine(Stat.Mp);
        }

        public IAction CombineApBack()
            => Combine(Stat.Ap);

        #region ASSETS
        private const string Icon_Base64 = "";
        private const string Bg_Base64 = "";
        #endregion
    }
}
